function.arguments:
{
  "database": "video_game_store",
  "collection": "Customers",
  "pipeline": [
    {
      "$match": {
        "Game Genre": "Strategy",
        "Purchase Date": {
          "$gte": {
            "$date": "2021-01-01"
          },
          "$lte": {
            "$date": "2023-12-31"
          }
        }
      }
    },
    {
      "$group": {
        "_id": "$Game Title",
        "average_rating": {
          "$avg": "$Customer Rating"
        },
        "total_sales": {
          "$sum": "$Purchase Amount"
        }
      }
    },
    {
      "$match": {
        "total_sales": {
          "$gte": 200
        }
      }
    },
    {
      "$sort": {
        "average_rating": 1,
        "total_sales": -1
      }
    },
    {
      "$limit": 1
    },
    {
      "$project": {
        "Game Title": "$_id",
        "average_rating": 1,
        "total_sales": 1,
        "_id": 0
      }
    }
  ]
}

